def average(marks):
    total = 0
    for mark in marks:
        total = total + mark
    return total / len(marks)

def print_result(name, marks):
    avg = average(marks)
    if avg >= 50:
        print(name, "pass", avg)
    else:
        print(name, "fail", avg)

print_result("Ada", [40, 60, 71])
print_result("Bo", [30, 45])

class Parcel:
    def __init__(self, parcel_id, weight):
        self.__parcel_id = parcel_id      # set once: no setter
        self.__weight = weight            # set once: no setter
        self.__status = "packed"

    def get_parcel_id(self):
        return self.__parcel_id

    def get_status(self):
        return self.__status

    def set_status(self, new_status):
        if new_status in ("packed", "sent", "delivered"):
            self.__status = new_status
        else:
            raise ValueError("invalid status")

p = Parcel("P17", 2.5)
p.set_status("sent")
print(p.get_parcel_id(), p.get_status())

class Vehicle:
    def __init__(self, reg, seats):
        self.__reg = reg
        self.__seats = seats

    def get_reg(self):
        return self.__reg

    def describe(self):
        return self.__reg + " seats " + str(self.__seats)

class Lorry(Vehicle):
    def __init__(self, reg, seats, payload):
        super().__init__(reg, seats)      # run the base-class constructor
        self.__payload = payload          # attribute only Lorry has

    def get_payload(self):
        return self.__payload

    def describe(self):                   # overrides Vehicle.describe
        return super().describe() + " payload " + str(self.__payload)

v = Vehicle("AB1", 5)
l = Lorry("LX9", 2, 7500)
print(v.describe())
print(l.describe(), l.get_reg())

class Notification:
    def send(self, message):
        raise NotImplementedError

class EmailNotification(Notification):
    def send(self, message):
        return f"Email: {message}"

class TextNotification(Notification):
    def send(self, message):
        return f"SMS: {message}"

def send_alert(channel, message):
    print(channel.send(message))

send_alert(EmailNotification(), "Exam at 09:00")
send_alert(TextNotification(), "Exam at 09:00")

class Track:
    def __init__(self, title, seconds):
        self.__title = title
        self.__seconds = seconds

    def get_seconds(self):
        return self.__seconds

class Playlist:
    def __init__(self, name):
        self.__name = name
        self.__tracks = []                # Playlist HAS tracks

    def add_track(self, title, seconds):
        self.__tracks.append(Track(title, seconds))

    def total_seconds(self):
        total = 0
        for t in self.__tracks:
            total = total + t.get_seconds()
        return total

mix = Playlist("Study")
mix.add_track("Intro", 90)
mix.add_track("Focus", 215)
print(mix.total_seconds())
